const body = $input.first().json.body || $input.first().json;
const message = body.message || '';
const history = body.messageHistory || [];
const sessionId = body.sessionId || 'unknown';
const visitorName = body.visitorName || 'Visitor';

// Detect intent
const lower = message.toLowerCase();
let intent = 'general';
if (lower.includes('test ride') || lower.includes('test drive')) intent = 'test-ride';
else if (lower.includes('price') || lower.includes('cost') || lower.includes('lakh')) intent = 'pricing';
else if (lower.includes('charg') || lower.includes('battery')) intent = 'charging';
else if (lower.includes('service') || lower.includes('repair')) intent = 'service';
else if (lower.includes('book') || lower.includes('appointment')) intent = 'booking';

return [{
  json: {
    message,
    intent,
    sessionId,
    visitorName,
    messageHistory: history,
    timestamp: new Date().toISOString()
  }
}];

const aiMessage = $input.first().json.message?.content || $input.first().json.choices?.[0]?.message?.content || 'I apologize, I could not process your request.';

return [{
  json: {
    success: true,
    response: aiMessage,
    intent: $('Parse & Detect Intent').item.json.intent,
    sessionId: $('Parse & Detect Intent').item.json.sessionId,
    timestamp: new Date().toISOString()
  }
}];
